-- ============================================
-- POSTGRES · SALES DEPARTMENT
-- 3 tables · 9 columns each · 1000 rows each
-- Run: docker exec -i pg_db psql -U postgres -d postgres < postgres_sales.sql
-- ============================================

DROP TABLE IF EXISTS orders CASCADE;
DROP TABLE IF EXISTS customers CASCADE;
DROP TABLE IF EXISTS sales_reps CASCADE;

CREATE TABLE customers (
    customer_id   SERIAL PRIMARY KEY,
    full_name     VARCHAR(120) NOT NULL,
    email         VARCHAR(150) UNIQUE NOT NULL,
    city          VARCHAR(80),
    state         VARCHAR(80),
    phone         VARCHAR(20),
    segment       VARCHAR(40),
    signup_date   DATE NOT NULL,
    is_active     BOOLEAN DEFAULT TRUE
);

CREATE TABLE sales_reps (
    rep_id          SERIAL PRIMARY KEY,
    full_name       VARCHAR(120) NOT NULL,
    email           VARCHAR(150) UNIQUE NOT NULL,
    region          VARCHAR(60),
    hire_date       DATE NOT NULL,
    target_amount   NUMERIC(12,2),
    achieved_amount NUMERIC(12,2),
    commission_pct  NUMERIC(5,2),
    is_active       BOOLEAN DEFAULT TRUE
);

CREATE TABLE orders (
    order_id        SERIAL PRIMARY KEY,
    customer_id     INTEGER REFERENCES customers(customer_id),
    rep_id          INTEGER REFERENCES sales_reps(rep_id),
    order_date      DATE NOT NULL,
    status          VARCHAR(30),
    channel         VARCHAR(40),
    discount_pct    NUMERIC(5,2),
    total_amount    NUMERIC(12,2),
    tax_amount      NUMERIC(10,2)
);



